<script>
(()=>{const button=document.getElementById('health-refresh');const results=document.getElementById('system-health-results');const error=document.getElementById('health-refresh-error');if(!button||!results)return;const original=button.innerHTML;button.addEventListener('click',async()=>{button.disabled=true;button.innerHTML='<span class="material-symbols-outlined animate-spin text-lg" aria-hidden="true">progress_activity</span><span>Checking…</span>';error.classList.add('hidden');results.setAttribute('aria-busy','true');const previous=results.innerHTML;results.innerHTML='<div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4" aria-label="Loading health checks"><div class="h-28 animate-pulse rounded-2xl bg-slate-200"></div><div class="h-28 animate-pulse rounded-2xl bg-slate-200"></div><div class="h-28 animate-pulse rounded-2xl bg-slate-200"></div><div class="h-28 animate-pulse rounded-2xl bg-slate-200"></div><div class="h-56 animate-pulse rounded-2xl bg-slate-200 sm:col-span-2 xl:col-span-4"></div></div>';try{const response=await fetch(window.location.href,{method:'GET',cache:'no-store',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'text/html'}});if(!response.ok)throw new Error('refresh_failed');const html=await response.text();const doc=new DOMParser().parseFromString(html,'text/html');const fresh=doc.getElementById('system-health-results');if(!fresh)throw new Error('refresh_failed');results.replaceChildren(...[...fresh.childNodes].map(node=>document.importNode(node,true)));results.setAttribute('aria-busy','false');}catch{results.innerHTML=previous;results.setAttribute('aria-busy','false');error.classList.remove('hidden');error.scrollIntoView({behavior:'smooth',block:'nearest'});}finally{button.disabled=false;button.innerHTML=original;}});})();
</script></body></html>
